package au.monster.tracker;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.net.Uri;
import android.text.InputType;
import android.widget.*;
import android.view.*;
import java.io.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Portable encrypted backups, explicit merge preview and scheduled local/provider copies. */
public final class BackupActivity extends Activity {
    private Store store;private BackupSettings settings;private TextView status;private LinearLayout body;private boolean busy,dead;private char[] exportPassword;private Uri deferredUri;private int deferredRequest;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);settings=new BackupSettings(this);if(b!=null){deferredRequest=b.getInt("request",0);String uri=b.getString("uri");if(uri!=null)deferredUri=Uri.parse(uri);}show();if(deferredUri!=null)resumeDocument();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("request",deferredRequest);if(deferredUri!=null)b.putString("uri",deferredUri.toString());}
    @Override protected void onDestroy(){dead=true;if(exportPassword!=null)Arrays.fill(exportPassword,'\0');io.execute(store::close);io.shutdown();super.onDestroy();}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(0xfff0f5eb);t.setPadding(0,dp(8),0,dp(8));return t;}
    private Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setMinHeight(dp(56));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    private void error(Throwable e){new AlertDialog.Builder(this).setTitle("Backup not completed").setMessage(e.getMessage()==null?"Existing records and recovery copies remain unchanged.":e.getMessage()).setPositiveButton("OK",null).show();}
    private <T> void job(Callable<T> task,java.util.function.Consumer<T> done){if(busy)return;busy=true;status.setText("Working locally…");io.execute(()->{try{T value=task.call();runOnUiThread(()->{if(dead)return;busy=false;done.accept(value);resumeDocument();});}catch(Throwable e){runOnUiThread(()->{if(dead)return;busy=false;status.setText("Existing records remain intact.");error(e);resumeDocument();});}});}
    private void show(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101410);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop()+dp(8),dp(16),insets.getSystemWindowInsetBottom()+dp(8));return insets;});setContentView(root);root.requestApplyInsets();root.addView(text("Encrypted backups & recovery",24));status=text(settings.status(),14);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(button("Export portable encrypted backup",()->password(true,p->{exportPassword=p;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/octet-stream");intent.putExtra(Intent.EXTRA_TITLE,"monster-"+LocalDate.now(Ledger.PERTH)+".monsterbackup");try{startActivityForResult(intent,91);}catch(ActivityNotFoundException e){Arrays.fill(exportPassword,'\0');exportPassword=null;error(e);}})));body.addView(button("Restore encrypted backup (preview first)",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),92);}catch(ActivityNotFoundException e){error(e);}}));body.addView(button("Set / change automatic-backup password",()->password(true,p->job(()->{try{settings.savePassword(p);return true;}finally{Arrays.fill(p,'\0');}},ok->{show();status.setText("Password saved securely on this device. Keep the same password outside this phone for recovery.");}))));CheckBox enabled=new CheckBox(this);enabled.setText("Enable scheduled encrypted backups");enabled.setTextColor(0xfff0f5eb);enabled.setChecked(settings.enabled());enabled.setMinHeight(dp(56));body.addView(enabled);Spinner frequency=new Spinner(this);frequency.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Daily (Android may delay while idle)","Weekly"}));frequency.setSelection(settings.hours()==168?1:0);body.addView(frequency);body.addView(button("Save backup schedule",()->{try{settings.schedule(enabled.isChecked(),frequency.getSelectedItemPosition()==0?24:168);BackupJob.schedule(this);show();status.setText(settings.enabled()?"Schedule enabled. Use Back up now to create the first verified copy.":"Automatic backups disabled.");}catch(Exception e){error(e);}}));body.addView(button("Back up now (local recovery + selected folder)",this::backupNow));body.addView(text("Optional folder: "+(settings.folder().isEmpty()?"not selected; app-private recovery only":settings.folder()),14));body.addView(button("Choose backup folder / optional provider",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION),93);}catch(ActivityNotFoundException e){error(e);}}));body.addView(button("Use local recovery copies only",()->{settings.folder("");show();}));body.addView(button("View local recovery copies",this::recovery));body.addView(text("Keep the password outside this phone. It cannot be recovered if lost. Password changes protect new backups; older copies still require their original password. AES-256-GCM authenticates the entire encrypted file. Full backups include sales, purchases, receipts, inventory, corrections, financial snapshots and business settings. Stripe pairing credentials, Android permissions and the scheduled-backup password are excluded; reconfigure those on a replacement phone.",15));body.addView(text("The latest seven verified automatic copies are kept app-private. Uninstalling, clearing data or losing the phone removes those copies. Select a folder or export/copy a backup elsewhere. Android file providers may include cloud storage; uploads need that provider's connectivity/setup and are not guaranteed by this app. Folder readback verifies copied bytes, not remote cloud durability. Background timing depends on Android battery restrictions. JSON/CSV exports remain available in the existing settings.",15));body.addView(button("Back to tracker",this::finish));}
    private void password(boolean confirm,java.util.function.Consumer<char[]> done){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),0,dp(16),0);EditText first=new EditText(this);first.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);first.setHint("Backup password (at least 10 characters)");first.setMinHeight(dp(56));box.addView(first);EditText second=new EditText(this);if(confirm){second.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);second.setHint("Repeat password");second.setMinHeight(dp(56));box.addView(second);}box.addView(text("Keep this password somewhere safe outside this phone. Existing records will not be replaced silently.",14));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(confirm?"Choose portable backup password":"Decrypt backup").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Continue",null).create();dialog.getWindow();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{char[] p=first.getText().toString().toCharArray();try{EncryptedBackup.password(p);if(confirm&&!Arrays.equals(p,second.getText().toString().toCharArray()))throw new IllegalArgumentException("Passwords do not match.");first.setText("");second.setText("");dialog.dismiss();done.accept(p);}catch(Exception e){Arrays.fill(p,'\0');error(e);}}));dialog.show();dialog.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);}
    private void backupNow(){if(!settings.configured()){error(new IllegalStateException("Set an automatic-backup password first. Export portable backup is also available."));return;}job(()->{char[] p=settings.password();try{File file=BackupFiles.create(this,p);BackupFiles.retain(this,7);String message="Verified local recovery backup saved.";try{BackupFiles.copy(this,file,settings.folder());if(!settings.folder().isEmpty())message+=" Provider folder copy verified.";}catch(Exception e){message+=" Provider copy failed; local copy remains safe: "+e.getMessage();}settings.status(message+" "+Ledger.displayTime(System.currentTimeMillis()));return message;}finally{Arrays.fill(p,'\0');}},message->{show();status.setText(message);});}
    private void recovery(){try{var files=BackupFiles.files(this);String[] names=files.stream().map(f->f.getName()+" · "+Ledger.displayTime(f.lastModified())).toArray(String[]::new);if(files.isEmpty()){error(new IllegalStateException("No local recovery copy exists yet. Set a password and use Back up now."));return;}new AlertDialog.Builder(this).setTitle("Verified local recovery copies").setItems(names,(d,index)->password(false,p->job(()->{try(InputStream in=new FileInputStream(files.get(index))){return EncryptedBackup.decode(BackupFiles.read(in),p);}finally{Arrays.fill(p,'\0');}},this::preview))).setNegativeButton("Close",null).show();}catch(Exception e){error(e);}}
    private void preview(Backup.Data incoming){var current=store.snapshot();try{int added=Ledger.merge(current.events(),incoming.events()).size()-current.events().size();new AlertDialog.Builder(this).setTitle("Merge validated encrypted backup?").setMessage("Current events: "+current.events().size()+"\nNew events: "+added+"\nExisting matching IDs are skipped. Conflicts reject the whole restore. Saved history is never deleted.\n\nFuture sale prices, stock thresholds and GST settings will be restored from this backup. Supplier originals and audit history are included. Export a fresh backup first if needed.").setNegativeButton("Cancel",null).setPositiveButton("Merge & restore",(d,w)->job(()->store.importBackup(incoming),count->{show();status.setText("Restored "+count+" new events; existing history retained.");})).show();}catch(Exception e){error(e);}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==91&&exportPassword!=null){Arrays.fill(exportPassword,'\0');exportPassword=null;}return;}Uri uri=data.getData();if(busy){deferredUri=uri;deferredRequest=request;return;}if(request==93){try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,flags);settings.folder(uri.toString());show();status.setText("Folder selected. Use Back up now to verify a real write and readback.");}catch(Exception e){error(e);}return;}if(request==91){if(exportPassword==null){password(true,p->{exportPassword=p;onActivityResult(91,RESULT_OK,new Intent().setData(uri));});return;}char[] p=exportPassword;exportPassword=null;job(()->{try{byte[] bytes=EncryptedBackup.encrypt(Backup.encode(store.fullBackup()).getBytes(java.nio.charset.StandardCharsets.UTF_8),p);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Destination cannot be opened.");out.write(bytes);out.flush();}try(InputStream in=getContentResolver().openInputStream(uri)){EncryptedBackup.decode(BackupFiles.read(in),p);}return true;}finally{Arrays.fill(p,'\0');}},ok->{show();status.setText("Encrypted backup written and readback validated. Keep the file and password outside this phone.");});}else if(request==92)password(false,p->job(()->{try(InputStream in=getContentResolver().openInputStream(uri)){return EncryptedBackup.decode(BackupFiles.read(in),p);}finally{Arrays.fill(p,'\0');}},this::preview));}
    private void resumeDocument(){if(deferredUri!=null&&!busy){Uri uri=deferredUri;int request=deferredRequest;deferredUri=null;deferredRequest=0;onActivityResult(request,RESULT_OK,new Intent().setData(uri));}}
}
